const SERVER_UNAVAILABLE_REASONS = [
  'handshake_missing',
  'handshake_invalid',
  'process_not_running',
  'health_check_failed',
  'plugin_context_mismatch',
  'telemetry_policy_mismatch',
  'server_starting',
  'transport_failed',
  'server_shutdown_pending',
  'server_start_timeout',
  'server_process_exited',
  'server_upgrade_required',
  'replacement_version_mismatch',
  'replacement_health_failed',
  'app_health_failed',
  'dev_server_resolution_failed',
  'rivet_port_unavailable',
  'editor_server_start_failed',
] as const;

export type ServerUnavailableReason =
  (typeof SERVER_UNAVAILABLE_REASONS)[number];

const serverUnavailableReasons = new Set<string>(SERVER_UNAVAILABLE_REASONS);

export const isServerUnavailableReason = (
  value: unknown,
): value is ServerUnavailableReason =>
  typeof value === 'string' && serverUnavailableReasons.has(value);
